FUNCTION_BLOCK constantprogram
VAR_INPUT
    i : INT;
END_VAR
VAR_OUTPUT
    o : INT;
    c : INT;
END_VAR

VAR
    constantValue : INT := 43;
END_VAR

BEGIN
    // Set the first output 'o' to the input value 'i'
    o := i;

    // Set the second output 'c' to the constant value 43
    c := constantValue;
END_FUNCTION_BLOCK
